async function labelsAI(req){const json=(o,status=200)=>new Response(JSON.stringify(o),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});try{if(req.method!=='POST')return json({error:'Method not allowed'},405);const origin=req.headers.get('origin');if(origin&&origin!==new URL(req.url).origin)return json({error:'Forbidden'},403);const userKey=req.headers.get('x-nova-ai-key');const aiKey=userKey&&/^AIza[A-Za-z0-9_-]{20,}$/.test(userKey)?userKey:(typeof GEMINI_API_KEY!=='undefined'?GEMINI_API_KEY:'');const body=await req.json();const items=body.items;if(!Array.isArray(items)||items.length<1||items.length>25)return json({error:'Invalid items'},400);if(!aiKey)return json({error:'AI unavailable'},503);const prompt="You are a clinical drafting assistant to a licensed pharmacist preparing Arabic medicine labels. Produce a practical SINGLE proposed instruction per item, not generic refusal. First preserve any explicit prescription directions exactly. Otherwise, if the drug identity, strength, formulation, patient age, weight where relevant, and indication are sufficient to support one conventional labeled regimen, propose that regimen with dose, route, frequency, and timing in concise Arabic. Treat every generated regimen as a pharmacist-review draft, never as a verified prescription. Do not guess the indication, formulation, treatment duration, or missing pediatric weight. For drugs with indication-dependent doses (including metformin), combination products with varying formulations (including Solpadeine), children, pregnancy, breastfeeding, renal impairment, or clinically important uncertainty, give only safe administration guidance when supported and clearly state what pharmacist must verify; never fabricate a dose. If pregnancy or breastfeeding is yes, do not assert safety; flag for clinical verification. Avoid unsupported claims. Do not replace a valid existing instruction. Output JSON with items array same length/order, each {instructions:string,warnings:string}; concise Arabic. warnings must contain only patient-specific clinically relevant medication safety alerts grounded in supplied information (contraindications, significant interactions between listed medicines, pregnancy/breastfeeding, missing pediatric weight, or required verification); if no substantiated alert use empty string. Do not invent renal disease, allergies, indications or drug interactions. Keep instructions under 180 characters and warnings under 220 characters. Input: "+JSON.stringify({items:items.map(x=>({name:String(x.name).slice(0,140),instructions:String(x.instructions||'').slice(0,250)})),age:String(body.age||'').slice(0,20),weight:String(body.weight||'').slice(0,20),preg:String(body.preg||'').slice(0,20),breast:String(body.breast||'').slice(0,20)});const result=await generateJsonWithDiscoveredModel({apiKey:aiKey,prompt,maxOutputTokens:4096,maxModels:4,retriesPerModel:1,responseSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{instructions:{type:'string'},warnings:{type:'string'}} ,required:['instructions','warnings']}}},required:['items']}});const parsed=result.data;if(!Array.isArray(parsed.items)||parsed.items.length!==items.length||parsed.items.some(x=>typeof x?.instructions!=='string'||!x.instructions.trim()))return json({error:'Gemini returned incomplete instructions; please retry',code:'INCOMPLETE_INSTRUCTIONS'},502);return json({items:items.map((_,i)=>({instructions:parsed.items[i].instructions.trim().slice(0,300),warnings:String(parsed.items[i].warnings||'').trim().slice(0,300)}))})}catch(e){return json({error:'AI processing failed'},500)}}

const aiUsage=new Map();
async function purchaseAI(req){
const json=(obj,status=200)=>new Response(JSON.stringify(obj),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
try{
if(req.method!=='POST')return json({error:'Method not allowed'},405);
const origin=req.headers.get('Origin');if(origin&&origin!==new URL(req.url).origin)return json({error:'Forbidden origin'},403);
const size=Number(req.headers.get('content-length')||0);if(size>22500000)return json({error:'File too large'},413);
const ip=req.headers.get('cf-connecting-ip')||'unknown',now=Date.now(),v=aiUsage.get(ip)||{count:0,at:now};
if(now-v.at>3600000){v.count=0;v.at=now}if(++v.count>5)return json({error:'تم تجاوز حد التجربة (5 طلبات في الساعة)'},429);aiUsage.set(ip,v);
const userKey=req.headers.get('x-nova-ai-key');const aiKey=userKey&&/^AIza[A-Za-z0-9_-]{20,}$/.test(userKey)?userKey:(typeof GEMINI_API_KEY!=='undefined'?GEMINI_API_KEY:'');const body=await req.json(),imgs=body.images;
if(!Array.isArray(imgs)||imgs.length<1||imgs.length>4||imgs.some(x=>!['image/jpeg','image/png','image/webp'].includes(x.mimeType)||typeof x.data!=='string'||x.data.length>5600000))return json({error:'Invalid images'},400);
if(!aiKey)return json({error:'Gemini API key is missing'},503);
const prompt='You are an Egyptian pharmacy purchase invoice OCR assistant. Extract all invoice rows from images. Return ONLY valid JSON object with supplier string and items array. Each item keys: name, quantity, unit_price, discount, batch, expiry, notes. Use original Arabic drug names as printed. Never invent missing or unreadable values; use empty string. Do not calculate missing prices. Do not infer batch or expiry. Do not combine unrelated rows. No markdown.';
const parts=[{text:prompt},...imgs.map(x=>({inline_data:{mime_type:x.mimeType,data:x.data}}))];
let upstream;let lastStatus=0;for(const model of ['gemini-2.5-flash','gemini-2.5-flash-lite']){upstream=await fetch('https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent',{method:'POST',headers:{'content-type':'application/json','x-goog-api-key':aiKey},body:JSON.stringify({contents:[{parts}],generationConfig:{responseMimeType:'application/json',temperature:0.1,maxOutputTokens:8192}})});lastStatus=upstream.status;if(upstream.status!==404)break;}
if(!upstream.ok){const err=await upstream.text();let upstreamError={};try{upstreamError=JSON.parse(err).error||{}}catch{};const reason=upstreamError.details?.flatMap(d=>d.reason?[d.reason]:[])?.[0]||'';return json({error:upstream.status===404?'موديل Gemini غير متاح لهذا المشروع (404)':upstream.status===401?'مشكلة في مصادقة مفتاح Gemini (401)':upstream.status===403?'المشروع غير مصرح له باستخدام Gemini (403)':upstream.status===429?'تم تجاوز حصة Gemini (429)':upstream.status===503?'خدمة Gemini مشغولة مؤقتًا (503)':'Gemini error '+upstream.status,diagnostic:{http_status:upstream.status,google_status:String(upstreamError.status||''),reason:String(reason),message:String(upstreamError.message||'').slice(0,260).replace(/AQ\.[A-Za-z0-9_-]+|AIza[A-Za-z0-9_-]+/g,'[redacted]')}},502)}
const result=await upstream.json(),raw=result.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('')||'';
let parsed;try{parsed=JSON.parse(raw)}catch{return json({error:'AI returned invalid JSON'},502)}
return json({supplier:String(parsed.supplier||''),items:Array.isArray(parsed.items)?parsed.items.slice(0,250).map(x=>({name:String(x.name||''),quantity:String(x.quantity??''),unit_price:String(x.unit_price??''),discount:String(x.discount??''),batch:String(x.batch||''),expiry:String(x.expiry||''),notes:String(x.notes||'')})):[]});
}catch(e){return json({error:'تعذر معالجة الطلب'},500)}
}

