export default {fetch(request,env,ctx){
let listener=NOVA_RUNTIMES.get(env);if(!listener){listener=novaRuntime(env);NOVA_RUNTIMES.set(env,listener);}
let response;listener({request,respondWith(value){if(response!==undefined)throw Error('duplicate response');response=value;},waitUntil:ctx.waitUntil.bind(ctx),passThroughOnException:ctx.passThroughOnException.bind(ctx)});
if(response===undefined)throw Error('fetch listener did not respond');return Promise.resolve(response);
}};
